<?php
session_start();require __DIR__.'/../config/database.php';require __DIR__.'/../includes/helpers.php';require_login();$uid=$_SESSION['user']['id'];
$st=$pdo->prepare('SELECT t.*, COUNT(DISTINCT tm_all.id) member_count, COALESCE((SELECT SUM(e2.amount) FROM expenses e2 WHERE e2.trip_id=t.id),0) spent, CASE WHEN t.owner_id=? THEN 1 ELSE 0 END is_owner FROM trips t JOIN trip_members tm_me ON tm_me.trip_id=t.id AND tm_me.user_id=? LEFT JOIN trip_members tm_all ON tm_all.trip_id=t.id WHERE t.owner_id=? OR tm_me.user_id=? GROUP BY t.id ORDER BY t.start_date DESC');$st->execute([$uid,$uid,$uid,$uid]);$trips=$st->fetchAll();
$pageTitle='Chuyến đi của tôi';include __DIR__.'/../includes/header.php';show_flash();
?>
<div class="page-shell"><div class="d-flex flex-column flex-md-row justify-content-between align-items-md-end gap-3 mb-4"><div><div class="eyebrow">MY TRIPS</div><h1 class="page-title">Chuyến đi của tôi</h1><div class="subtext mt-1">Tạo, chỉnh sửa và theo dõi toàn bộ hành trình của bạn, bao gồm cả các chuyến đi được bạn bè chia sẻ.</div></div><a href="<?= base_url('user/trip-create.php') ?>" class="btn btn-primary rounded-3">＋ Tạo chuyến đi</a></div>
<div class="row g-4"><?php foreach($trips as $t): $pct=$t['budget']>0?min(100,round(($t['spent']/$t['budget'])*100)):0; ?><div class="col-md-6 col-xl-4"><div class="panel h-100"><div class="d-flex justify-content-between align-items-center"><div><span class="pill"><?= e($t['destination']) ?></span><?php if(!(int)$t['is_owner']): ?><span class="pill ms-1">Được chia sẻ</span><?php endif; ?></div><span class="small text-secondary"><?= e($t['status']) ?></span></div><h3 class="fs-5 fw-800 mt-3"><?= e($t['name']) ?></h3><div class="subtext"><?= e($t['start_date']) ?> → <?= e($t['end_date']) ?></div><div class="d-flex justify-content-between small mt-4"><span>Đã chi</span><strong><?= number_format($t['spent'],0,',','.') ?>đ</strong></div><div class="metric-bar mt-1"><span style="width:<?= $pct ?>%"></span></div><div class="d-flex justify-content-between small text-secondary mt-2"><span><?= $pct ?>% ngân sách</span><span>👥 <?= (int)$t['member_count'] ?></span></div><a class="btn btn-dark w-100 mt-4 rounded-3" href="<?= base_url('user/trip-detail.php?id='.$t['id']) ?>">Mở kế hoạch</a></div></div><?php endforeach; ?><?php if(!$trips): ?><div class="col-12"><div class="empty-state">Chưa có chuyến đi. Hãy tạo chuyến đầu tiên.</div></div><?php endif; ?></div></div>
<?php include __DIR__.'/../includes/footer.php'; ?>
